def transform(grid):
    a=[row[:] for row in grid]
    n=len(a)
    for r in range(n):
        for c in range(r+1,n):
            if a[r][c]==6 and a[c][r]!=6: a[r][c]=a[c][r]
            elif a[c][r]==6 and a[r][c]!=6: a[c][r]=a[r][c]
    unknown=[(r,c) for r in range(n) for c in range(r,n) if a[r][c]==6]
    for r,c in unknown:
        ctx=[]
        for d in range(-5,6):
            if d==0: continue
            if 0<=c+d<n and a[r][c+d]!=6: ctx.append(('h',d,a[r][c+d]))
            if 0<=r+d<n and a[r+d][c]!=6: ctx.append(('v',d,a[r+d][c]))
        candidates=[]
        for orient in ('h','v'):
            for rr in range(n):
                for cc in range(n):
                    val=a[rr][cc]
                    if val==6 or (rr==r and cc==c): continue
                    matches=total=0
                    for o,d,v in ctx:
                        if o!=orient: continue
                        ar,ac=(rr,cc+d) if o=='h' else (rr+d,cc)
                        if 0<=ar<n and 0<=ac<n and a[ar][ac]!=6:
                            total+=1
                            matches += a[ar][ac]==v
                    if total>=4: candidates.append((matches/total,matches,total,val))
        if candidates:
            best=max((x[0],x[1],x[2]) for x in candidates)
            vals=[x[3] for x in candidates if (x[0],x[1],x[2])==best]
            value=max(set(vals),key=vals.count)
